/**
 * Engine — reads CONFIG, loads components, renders & animates.
 * DO NOT edit this file for customization. Edit config.js only.
 */

// ── Theme ────────────────────────────────────────────────────────
let currentMode = (CONFIG.defaultMode || "dark");

function applyTheme(mode) {
  currentMode = mode;
  const root = document.documentElement;
  const c = CONFIG.colors;

  root.style.setProperty("--primary", c.primary || "#ff69b4");
  root.style.setProperty("--accent", c.accent || "#15a1ed");

  const theme = c[mode] || c.dark || {};
  root.style.setProperty("--bg", theme.background || "#1a1a2e");
  root.style.setProperty("--text", theme.text || "#ffffff");

  // Update toggle icon
  const btn = document.getElementById("theme-toggle");
  if (btn) btn.textContent = "◐";
}

function createThemeToggle() {
  const btn = document.createElement("button");
  btn.id = "theme-toggle";
  btn.title = "Toggle dark/light mode";
  btn.textContent = "◐";
  btn.addEventListener("click", () => {
    applyTheme(currentMode === "dark" ? "light" : "dark");
  });
  document.body.appendChild(btn);
}

// ── Script Loader ────────────────────────────────────────────────
function loadScript(src) {
  return new Promise((resolve, reject) => {
    const s = document.createElement("script");
    s.src = src;
    s.onload = resolve;
    s.onerror = () => reject(new Error("Component not found: " + src));
    document.head.appendChild(s);
  });
}


// ── Time Gate — unlocks 2026-11-19 00:00 (Asia/Shanghai) ────────────
const UNLOCK_AT = new Date("2026-11-19T00:00:00+08:00").getTime();
const TEST_PREVIEW = false;

function fmtRemain(ms) {
  const s = Math.max(0, Math.floor(ms / 1000));
  const d = Math.floor(s / 86400);
  const h = Math.floor((s % 86400) / 3600);
  const m = Math.floor((s % 3600) / 60);
  const sec = s % 60;
  const p = (n) => String(n).padStart(2, "0");
  return (d > 0 ? d + " 天 " : "") + p(h) + ":" + p(m) + ":" + p(sec);
}

function showLock() {
  const lock = document.getElementById("lock-screen");
  const count = document.getElementById("lock-count");
  if (!lock) return;
  lock.hidden = false;
  const tick = () => {
    const remain = UNLOCK_AT - Date.now();
    if (remain <= 0) {
      clearInterval(timer);
      lock.hidden = true;
      initSite();
      return;
    }
    if (count) count.textContent = fmtRemain(remain);
  };
  const timer = setInterval(tick, 500);
  tick();
}

// ── Main ─────────────────────────────────────────────────────────
document.addEventListener("DOMContentLoaded", async () => {
  if (!TEST_PREVIEW && Date.now() < UNLOCK_AT) {
    showLock();
    return;
  }
  await initSite();
});

async function initSite() {
  // Reduced motion: skip the film, offer the quiet reading page
  // (the same fallback HUMAN.md gives its readers).
  if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
    document.body.classList.add("reading");
    return;
  }
  applyTheme(currentMode);
  createThemeToggle();

  // Set music source(s): an array rotates — each track hands over to
  // the next when it ends, looping back to the first.
  const audio = document.querySelector(".song");
  if (audio && CONFIG.music) {
    const tracks = Array.isArray(CONFIG.music) ? CONFIG.music : [CONFIG.music];
    let trackIdx = 0;
    const setTrack = (i) => {
      audio.querySelector("source").src = tracks[i];
      audio.load();
    };
    setTrack(0);
    if (tracks.length > 1) {
      audio.addEventListener("ended", () => {
        trackIdx = (trackIdx + 1) % tracks.length;
        setTrack(trackIdx);
        audio.play().catch(() => {});
      });
    }
  }

  // Determine unique component types
  const types = [...new Set(CONFIG.sections.map((s) => s.type))];

  // Dynamically load component scripts
  for (const type of types) {
    try {
      await loadScript(`./script/components/${type}.js?v=1118`);
    } catch (e) {
      console.warn(e.message);
    }
  }

  // Render all sections
  const container = document.querySelector(".container");
  const rendered = [];

  CONFIG.sections.forEach((section) => {
    const comp = window.Components && window.Components[section.type];
    if (!comp) {
      console.warn(`Component "${section.type}" not found, skipping.`);
      return;
    }
    const el = comp.render(container, section, CONFIG);
    rendered.push({ el, comp, section });
  });

  // If the animation library somehow failed to load, fall back to the
  // plain-text reading version instead of a dead page.
  if (!window.gsap) { document.body.classList.add("reading"); return; }

  const start = (withMusic) => {
    if (withMusic && audio) { window.__musicOn = true; audio.play().catch(() => {}); }
    buildTimeline(rendered);
  };

  // SweetAlert music prompt (optional: if it failed to load, just start)
  if (!window.Swal) { start(false); return; }
  const isDark = currentMode === "dark";
  Swal.fire({
    title: "要為你放一首歌嗎？",
    showCancelButton: true,
    confirmButtonColor: CONFIG.colors.accent || "#3085d6",
    cancelButtonColor: "#888",
    confirmButtonText: "好啊",
    cancelButtonText: "不用了",
    background: isDark ? "#1e293b" : "#ffffff",
    color: isDark ? "#f1f5f9" : "#1e293b",
  }).then((result) => start(result.isConfirmed));
}

// ── Timeline Builder ─────────────────────────────────────────────
function buildTimeline(rendered) {
  const tl = gsap.timeline();
  window.__tl = tl;
  tl.eventCallback("onUpdate", () => {
    if (window.FilmHUD) FilmHUD.onProgress(tl);
  });

  tl.to(".container", { duration: 0.6, visibility: "visible" });

  // Track deferred exits for overlay components
  let deferredExits = [];
  const wipe = document.getElementById("wipe");
  let prevWasStage = false;

  rendered.forEach(({ el, comp, section }, i) => {
    const isOverlay = comp.overlay === true;

    // Flush deferred exits before non-overlay sections
    if (!isOverlay && deferredExits.length > 0) {
      deferredExits.forEach((fn) => fn());
      deferredExits = [];
    }

    // Chapter label (HUD crumb, progress, index seek)
    tl.addLabel("ch" + i);

    // Animate
    comp.animate(tl, el, CONFIG);
    if (!isOverlay) prevWasStage = true;

    // Handle exit lifecycle
    if (comp.exit) {
      const next = rendered[i + 1];
      const nextIsOverlay = next && next.comp.overlay === true;

      if (nextIsOverlay) {
        deferredExits.push(() => comp.exit(tl, el));
      } else if (!isOverlay) {
        comp.exit(tl, el);
      }
    }
  });

  // Flush remaining
  deferredExits.forEach((fn) => fn());

  // Setup replay
  const replayBtn = document.getElementById("replay");
  if (replayBtn) {
    replayBtn.addEventListener("click", () => tl.restart());
  }

  // Publish to the film layer (HUD / index / progress)
  if (window.FilmHUD) FilmHUD.bind(tl);
}
